public void postLoad()
{
    //Number Sequence constant values
    this.NumberSeqConstantDetails = this.numberSequenceConstantVal(this.Format);

    next postLoad();
}

/// <summary>
/// Based on LedgerJournal Name and Voucher series code, the constant values from the Number Sequence table will be retrieved
/// </summary>
private NumberSequenceCode numberSequenceConstantVal(NumberSequenceFormat _numberSequenceFormat)
{
    //Journal Name parameters
    LedgerJournalName                   ledgerJournalName;
    NumberSequenceFormat                numberSequenceFormat;

    NumberSequenceCode                  numberSequenceCodeLoc;

    int                                 counter;

    //Number Sequence  Format
    numberSequenceFormat = _numberSequenceFormat;

    //Loop through the Number Sequence Format - <dataareaid><constant><####...>
    for(counter=1;counter<=strLen(numberSequenceFormat);counter++)
    {
        //Exclude the # character
        if(subStr(numberSequenceFormat,counter,1)!="#")
        {
            if(counter>3)
            {
                //Number Sequence Code Constant
                numberSequenceCodeLoc += subStr(numberSequenceFormat,counter+1,1);

                //Remove special characters # in case if it is picked up
                numberSequenceCodeLoc = strReplace(numberSequenceCodeLoc,"#","");
            }
        }
    }

    return numberSequenceCodeLoc;

}
